pub fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (as described): start + sub.len() <= main.len()
    // If violated, we conservatively return false.
    if start > main.len() || sub.len() > main.len() - start {
        return false;
    }

    for (j, &val) in sub.iter().enumerate() {
        if main[start + j] != val {
            return false;
        }
    }
    true
}

pub fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Empty subarray always qualifies.
    if sub.is_empty() {
        return true;
    }
    if sub.len() > main.len() {
        return false;
    }

    let limit = main.len() - sub.len();
    for start in 0..=limit {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}